          "问题不在于不知道下一个面，而在于进入下一个面后不知道共享边的局部编号。把 nbr 从 Triangle 改成 EdgeRef=(t,i)，一次跨越就同时携带目标面和目标边号。",
          "i 只需表示 0、1、2，理论上可塞进三角形索引的空余比特，因此课程假设总存储不变。实现时即便先用独立整数，也应先保证语义和不变量正确。",
