          "object-order 从一个几何图元出发，将它投影并覆盖到像素。实际光栅化不会真的扫描每个像素，而会计算图元在屏幕上的包围区域和覆盖规则；课件用双循环只强调组织方式。",
          "这种顺序天然知道当前处理哪个对象，但多个对象争夺同一像素时还要通过深度测试解决可见性。后半课程的光栅化与 GPU 管线会走这条路线。",
